/* eslint-disable @typescript-eslint/no-explicit-any */
import { useEffect, useMemo, useState, type ComponentType, type ReactNode } from "react";
import { Link } from "react-router-dom";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertTriangle, Bell, CalendarDays, CheckCircle2, Crosshair, Eye, FileText, Map as MapIcon, MapPin, Radio, RefreshCw, Route, Search, ShieldAlert, ShieldCheck, Smartphone, Wifi, Zap } from "lucide-react";
import { format, formatDistanceToNow } from "date-fns";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useCompanyId } from "@/hooks/usePatrolScanData";
import { realtimeStatusLabel, useRealtimeConnectionStatus } from "@/hooks/useRealtimeConnectionStatus";
import { getSiteName, useSites } from "@/hooks/useSites";
import { usePlatformAdmin } from "@/hooks/usePlatformAdmin";
import { TTechMxPatrolLogo } from "@/components/branding/TTechMxPatrolLogo";
import LiveMap from "@/components/dashboard/LiveMap";
import { patrolSessionLabel, patrolSessionProgress, usePatrolRoutes, usePatrolSchedules, usePatrolSessions } from "@/hooks/useScheduledPatrols";

type DateRange = "today" | "7d" | "30d";
type Severity = "normal" | "info" | "warning" | "critical" | "offline";
type IconComponent = ComponentType<{ className?: string }>;
type AnyRow = Record<string, any>;
type QueryResponse = { data?: unknown; error?: { message?: string } | null };
type QueryBuilder = PromiseLike<QueryResponse> & { select: (columns: string) => QueryBuilder; eq: (column: string, value: unknown) => QueryBuilder; is: (column: string, value: unknown) => QueryBuilder; gte: (column: string, value: string) => QueryBuilder; order: (column: string, options?: { ascending?: boolean }) => QueryBuilder; limit: (count: number) => QueryBuilder; maybeSingle: () => QueryBuilder };
type SupabaseQueryClient = { from: (table: string) => QueryBuilder };
type ActivityEvent = { id: string; title: string; subtitle?: string; site?: string; route: string; timestamp?: string | null; severity: Severity };
type AttentionItem = { id: string; title: string; subject: string; site: string; state: string; route: string; timestamp?: string | null; severity: "warning" | "critical" | "offline" };
type CommandMetric = { label: string; value: string | number; hint?: string; tone?: Severity };
type CommandPanelModel = { title: string; icon: IconComponent; route: string; accent: Severity; metrics: CommandMetric[] };
type OverviewData = { companyName: string; scans: AnyRow[]; reports: AnyRow[]; reportJobs: AnyRow[]; alerts: AnyRow[]; incidents: AnyRow[]; devices: AnyRow[]; checkpoints: AnyRow[]; pendingTags: AnyRow[]; aiInsights: AnyRow[] };

const db = supabase as unknown as SupabaseQueryClient;
const dateRangeStart = (range: DateRange) => { const date = new Date(); if (range === "today") date.setHours(0, 0, 0, 0); if (range === "7d") date.setDate(date.getDate() - 7); if (range === "30d") date.setDate(date.getDate() - 30); return date.toISOString(); };

export default function CommandCenter() {
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const { isPlatformAdmin } = usePlatformAdmin();
  const { data: companyId, isLoading: companyLoading } = useCompanyId();
  const { data: sites = [] } = useSites();
  const [siteId, setSiteId] = useState("all");
  const [dateRange, setDateRange] = useState<DateRange>("today");
  const [lastUpdated, setLastUpdated] = useState(new Date());
  const realtime = useRealtimeConnectionStatus("command-center");
  const periodStart = useMemo(() => dateRangeStart(dateRange), [dateRange]);
  const overviewQueryKey = useMemo(() => ["command-center-overview", companyId, siteId, dateRange] as const, [companyId, siteId, dateRange]);
  const overview = useQuery({ queryKey: overviewQueryKey, enabled: !!companyId, staleTime: 15_000, queryFn: async () => fetchCommandCenterOverview(companyId!, siteId, periodStart) });
  const { data: sessions = [], isFetching: sessionsFetching } = usePatrolSessions(80, siteId);
  const { data: routes = [] } = usePatrolRoutes(siteId);
  const { data: schedules = [] } = usePatrolSchedules(siteId);

  useEffect(() => {
    if (!companyId) return;
    const tables = ["scan_logs", "alerts", "incidents", "devices", "checkpoints", "ai_reports", "report_jobs", "ai_insights"];
    const channel = supabase.channel(`command-center-${companyId}-${Date.now()}-${Math.random().toString(36).slice(2)}`);
    tables.forEach((table) => channel.on("postgres_changes", { event: "*", schema: "public", table, filter: `company_id=eq.${companyId}` }, (payload) => {
      console.info("[Command Center] realtime event received", { table, eventType: payload.eventType });
      setLastUpdated(new Date());
      void queryClient.invalidateQueries({ queryKey: overviewQueryKey, exact: true });
      void queryClient.refetchQueries({ queryKey: overviewQueryKey, exact: true, type: "active" });
      void queryClient.invalidateQueries({ queryKey: ["patrol_sessions", companyId] });
    }));
    channel.subscribe((status) => { if (status === "CHANNEL_ERROR") console.warn("[Command Center] realtime channel failed"); });
    return () => { void supabase.removeChannel(channel); };
  }, [companyId, overviewQueryKey, queryClient]);
  useEffect(() => { if (overview.data) setLastUpdated(new Date()); }, [overview.data]);

  const selectedSiteName = siteId === "all" ? "All Sites" : getSiteName(siteId, sites);
  const model = useMemo(() => buildOperationsModel(overview.data, sessions, periodStart, selectedSiteName), [overview.data, sessions, periodStart, selectedSiteName]);
  const commandPanels = useMemo(() => buildCommandPanels(model, routes, schedules), [model, routes, schedules]);
  const loading = overview.isLoading || companyLoading;
  const pageError = overview.error;
  const patrolRows = useMemo(() => sessions
    .filter((session) => String(session.scheduled_start ?? session.created_at ?? "") >= periodStart)
    .slice(0, 12), [periodStart, sessions]);

  return (
    <div className="min-h-full bg-[radial-gradient(circle_at_top_left,rgba(16,185,129,0.10),transparent_30%),radial-gradient(circle_at_top_right,rgba(14,165,233,0.10),transparent_32%),linear-gradient(180deg,rgba(2,6,23,0.98),rgba(2,8,23,1))] pb-5 text-white">
      <header className="mb-4 flex flex-col gap-4 border-b border-white/10 pb-4 xl:flex-row xl:items-start xl:justify-between">
        <div className="min-w-0"><div className="mb-3 flex items-center gap-3"><TTechMxPatrolLogo variant="header" priority className="w-32" /><span className="rounded-full border border-emerald-400/30 bg-emerald-400/10 px-2.5 py-1 text-[10px] font-black uppercase tracking-[0.14em] text-emerald-300"><span className="mr-1.5 inline-block h-1.5 w-1.5 rounded-full bg-emerald-300 animate-pulse" />Live</span></div><h1 className="text-3xl font-black tracking-tight text-white">Command Center</h1><p className="mt-1 text-sm text-slate-400">Real-time overview of security operations across all sites.</p></div>
        <div className="flex flex-wrap items-center gap-2"><HeaderPill icon={Wifi} label={realtimeStatusLabel(realtime.status)} tone={realtime.status === "live" ? "normal" : "warning"} /><HeaderPill icon={Bell} label={`${model.sosActive} SOS`} tone={model.sosActive ? "critical" : "normal"} /><HeaderPill icon={ShieldCheck} label={user?.email ?? "Security Supervisor"} tone="info" /></div>
      </header>
      <section className='mb-4 grid gap-3 xl:grid-cols-[1fr_auto] xl:items-center'><label className='relative block max-w-xl'><Search className='pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500' /><input className='h-11 w-full rounded-lg border border-cyan-400/30 bg-slate-950/78 pl-10 pr-4 text-sm font-semibold text-slate-200 outline-none placeholder:text-slate-500 focus:border-cyan-300/70' placeholder='Search patrols, devices, incidents...' /></label><span className='text-xs font-semibold uppercase tracking-[0.14em] text-slate-500'>Command scope: live production data</span></section>
      <section className="mb-4 grid gap-3 xl:grid-cols-[1fr_1fr_1fr_auto]"><Field label="Company"><select disabled={!isPlatformAdmin} className="h-10 w-full rounded-lg border border-white/10 bg-slate-950/78 px-3 text-sm font-semibold text-white outline-none disabled:opacity-80"><option>{overview.data?.companyName ?? "Current company"}</option></select></Field><Field label="Site"><select value={siteId} onChange={(event) => setSiteId(event.target.value)} className="h-10 w-full rounded-lg border border-white/10 bg-slate-950/78 px-3 text-sm font-semibold text-white outline-none focus:border-emerald-300/50"><option value="all">All Sites</option>{sites.map((site) => <option key={site.id} value={site.id}>{site.name}</option>)}</select></Field><Field label="Time Period"><select value={dateRange} onChange={(event) => setDateRange(event.target.value as DateRange)} className="h-10 w-full rounded-lg border border-white/10 bg-slate-950/78 px-3 text-sm font-semibold text-white outline-none focus:border-emerald-300/50"><option value="today">Today</option><option value="7d">Last 7 Days</option><option value="30d">Last 30 Days</option></select></Field><div className="flex items-end gap-3 text-sm text-slate-400"><span className="inline-flex h-10 items-center gap-2 whitespace-nowrap"><span className="h-2 w-2 rounded-full bg-emerald-300" />Last updated: {lastUpdated.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" })}</span><button onClick={() => void overview.refetch()} className="flex h-10 w-10 items-center justify-center rounded-lg border border-white/10 bg-slate-950/78 text-slate-300 transition hover:border-emerald-300/40 hover:text-emerald-300" aria-label="Refresh Command Center"><RefreshCw className={`h-4 w-4 ${overview.isFetching || sessionsFetching ? "animate-spin" : ""}`} /></button></div></section>
      {pageError && <section className="mb-4 rounded-xl border border-red-400/35 bg-red-500/10 p-4 text-sm text-red-200">One Command Center module could not load. Other panels remain available while Supabase retries.</section>}
      <section className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4 2xl:grid-cols-8"><KpiCard icon={ShieldCheck} title="Operational Health" value={loading ? "--" : `${model.healthScore}%`} detail={model.healthLabel} tone={model.healthScore < 75 ? "critical" : model.healthScore < 90 ? "warning" : "normal"} subtext={`Main risk: ${model.mainRisk}`} /><KpiCard icon={Route} title="Patrol Compliance" value={loading ? "--" : `${model.patrolCompliance}%`} detail={`${model.sessionsCompleted} of ${model.sessionsExpected} completed`} tone={model.patrolCompliance < 80 ? "warning" : "normal"} /><KpiCard icon={Zap} title="Active Patrols" value={model.activeSessions.length} detail="Now" tone={model.activeSessions.length ? "normal" : "info"} /><KpiCard icon={Smartphone} title="Devices Online" value={`${model.devicesOnline} / ${model.devicesTotal}`} detail={`${model.devicesOffline} offline`} tone={model.devicesOffline ? "warning" : "normal"} /><KpiCard icon={AlertTriangle} title="Open Incidents" value={model.openIncidents} detail={`${model.criticalIncidents} critical`} tone={model.criticalIncidents ? "critical" : model.openIncidents ? "warning" : "normal"} /><KpiCard icon={ShieldAlert} title="Active SOS" value={model.sosActive} detail={model.sosActive ? "Awaiting response" : "Clear"} tone={model.sosActive ? "critical" : "normal"} /></section>
      <section className="mb-4 grid gap-3 lg:grid-cols-2 2xl:grid-cols-4">{commandPanels.map((panel) => <CommandPanel key={panel.title} panel={panel} />)}</section>
      <PatrolsStatusPanel sessions={patrolRows} devices={overview.data?.devices ?? []} />
      <section className="mb-4 rounded-xl border border-red-400/20 bg-slate-950/72 p-4">
        <div className="mb-3 flex items-center justify-between gap-3"><h2 className="text-sm font-black uppercase tracking-[0.16em] text-white">Critical Attention</h2><span className="rounded-full border border-white/10 px-2 py-1 text-xs text-slate-400">{model.attention.length} active</span></div>
        {model.attention.length ? <div className="grid gap-3 xl:grid-cols-3">{model.attention.map((item) => <AttentionCard key={item.id} item={item} />)}</div> : <StateLine icon={CheckCircle2} text="No urgent unresolved operational issues for the selected scope." />}
      </section>
      <section className="mb-4 grid gap-4 xl:grid-cols-[1.1fr_1.1fr_1.35fr]">
        <OperationsPanel title="Live Activity Feed" action="View full activity" route="/scan-logs" badge="Live"><div className="max-h-[25rem] space-y-2 overflow-auto pr-1">{model.activity.length ? model.activity.slice(0, 24).map((event) => <ActivityRow key={event.id} event={event} />) : <StateLine icon={Radio} text="Waiting for live activity in this period." />}</div></OperationsPanel>
        <OperationsPanel title="Active Patrols" action="Open Live Patrol" route="/live-patrol" badge={`${model.activeSessions.length} active`}><div className="max-h-[25rem] space-y-3 overflow-auto pr-1">{model.activeSessions.length ? model.activeSessions.slice(0, 6).map((session) => <PatrolSessionCard key={session.id} session={session} />) : <NoActivePatrol next={model.nextSession} />}</div></OperationsPanel>
        <OperationsPanel title="Mini Live Map" action="Open Live Map" route="/live-map" badge="Map"><div className="h-[25rem] overflow-hidden rounded-lg border border-white/10 bg-slate-950/80"><LiveMap operationsMode showCheckpoints showDevices showRoutes showSos /></div></OperationsPanel>
      </section>
      <section className="mt-4 rounded-xl border border-white/10 bg-slate-950/72 p-4">
        <div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-black uppercase tracking-[0.14em] text-white">Quick Actions</h2><span className="text-xs text-slate-500">Role-scoped navigation</span></div>
        <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-8">
          <QuickAction to="/patrols" label="Create Patrol" />
          <QuickAction to="/incidents" label="Create Incident" />
          <QuickAction to="/devices" label="Register Device" />
          <QuickAction to="/live-map" label="Open Live Map" />
          <QuickAction to="/reports" label="Generate Report" />
          <QuickAction to="/sos-alerts" label="View SOS" critical={model.sosActive > 0} />
          <QuickAction to="/reports" label="Executive Export" />
        </div>
      </section>
      <footer className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/10 bg-slate-950/60 px-4 py-3 text-xs text-slate-400"><span>Operational Health = patrol compliance, device availability, unresolved incidents, active SOS, scan quality and pending tag risk.</span><span>{selectedSiteName} - {dateRangeLabel(dateRange)}</span></footer>
    </div>
  );
}

async function fetchCommandCenterOverview(companyId: string, siteId: string, periodStart: string): Promise<OverviewData> {
  const siteFilter = (query: QueryBuilder) => siteId === "all" ? query : query.eq("site_id", siteId);
  const latest = (table: string, select: string, order: string, apply?: (q: QueryBuilder) => QueryBuilder, limit = 1) => { let query = db.from(table).select(select).eq("company_id", companyId).order(order, { ascending: false }).limit(limit); if (apply) query = apply(query); return query; };
  const [companyRes, scansRes, reportsRes, jobsRes, alertsRes, incidentsRes, devicesRes, checkpointsRes, pendingRes, aiRes] = await Promise.all([
    db.from("companies").select("name").eq("id", companyId).maybeSingle(),
    latest("scan_logs", "id,company_id,site_id,checkpoint_id,device_identifier,device_id,tag_uid,tag_status,scanned_at,created_at,gps_lat,gps_lng,gps_accuracy,sites(name),checkpoints(name,site_id,sites(name))", "created_at", siteFilter, 120),
    latest("ai_reports", "id,report_type,summary_text,generated_at", "generated_at", (q) => q.gte("generated_at", periodStart), 30),
    latest("report_jobs", "id,report_type,status,error_message,created_at,completed_at,failed_at,scheduled_for,site_id,sites(name)", "created_at", (q) => siteFilter(q.gte("created_at", periodStart)), 50),
    latest("alerts", "id,type,severity,message,is_read,created_at,event_occurred_at,device_identifier,site_id,session_id,location_lat,location_lng,gps_accuracy", "created_at", (q) => q.eq("type", "panic_button"), 30),
    latest("incidents", "id,title,severity,status,resolved,site_id,created_at,sites(name)", "created_at", siteFilter, 50),
    latest("devices", "id,device_name,device_identifier,status,pairing_status,last_seen_at,site_id,sites(name),battery_level,current_battery_level,current_gps_lat,current_gps_lng,current_gps_accuracy", "last_seen_at", siteFilter, 80),
    latest("checkpoints", "id,name,nfc_tag_id,site_id,created_at,sites(name)", "created_at", siteFilter, 80),
    latest("scan_logs", "id,company_id,site_id,checkpoint_id,device_identifier,device_id,tag_uid,tag_status,scanned_at,created_at,gps_lat,gps_lng,sites(name)", "created_at", (q) => siteFilter(q.eq("tag_status", "unregistered").is("checkpoint_id", null)), 40),
    latest("ai_insights", "id,type,summary,severity,created_at", "created_at", undefined, 10),
  ]);
  const rows = (res: QueryResponse, label: string) => {
    if (res?.error) {
      console.warn(`[Command Center] ${label} query failed`, res.error);
      return [] as AnyRow[];
    }
    return (Array.isArray(res?.data) ? res.data : []) as AnyRow[];
  };
  const companyName = (companyRes?.data as { name?: string } | null | undefined)?.name ?? "Current company";
  if (companyRes?.error) console.warn("[Command Center] company query failed", companyRes.error);
  return { companyName, scans: rows(scansRes, "scan_logs"), reports: rows(reportsRes, "ai_reports"), reportJobs: rows(jobsRes, "report_jobs"), alerts: rows(alertsRes, "alerts"), incidents: rows(incidentsRes, "incidents"), devices: rows(devicesRes, "devices"), checkpoints: rows(checkpointsRes, "checkpoints"), pendingTags: rows(pendingRes, "scan_logs unregistered"), aiInsights: rows(aiRes, "ai_insights") };
}

function buildOperationsModel(data: OverviewData | undefined, sessions: AnyRow[], periodStart: string, selectedSiteName: string) {
  const scans = (data?.scans ?? []).filter((scan) => eventTime(scan) >= periodStart), devices = data?.devices ?? [], alerts = data?.alerts ?? [], incidents = data?.incidents ?? [], reports = data?.reports ?? [], jobs = data?.reportJobs ?? [], checkpoints = data?.checkpoints ?? [], pendingTags = (data?.pendingTags ?? []).filter((tag) => eventTime(tag) >= periodStart), aiInsights = (data?.aiInsights ?? []).filter((item) => item.type !== "camera_detection");
  const activeSessions = sessions.filter((s) => ["active", "in_progress", "running"].includes(String(s.status)));
  const nextSession = sessions.find((s) => ["scheduled", "awaiting_start"].includes(String(s.status)));
  const expectedSessions = sessions.filter((s) => String(s.scheduled_start ?? s.created_at ?? "") >= periodStart && !["cancelled", "paused"].includes(String(s.status)));
  const completedSessions = expectedSessions.filter((s) => ["completed", "completed_late"].includes(String(s.status)));
  const lateSessions = expectedSessions.filter((s) => ["completed_late", "late", "delayed"].includes(String(s.status)));
  const missedSessions = expectedSessions.filter((s) => ["missed", "incomplete"].includes(String(s.status)));
  const registeredScans = scans.filter((s) => s.checkpoint_id || s.tag_status === "registered");
  const unregisteredScans = scans.filter((s) => s.tag_status === "unregistered" || !s.checkpoint_id);
  const patrolCompliance = expectedSessions.length ? Math.round((completedSessions.length / expectedSessions.length) * 100) : (scans.length ? Math.round((registeredScans.length / scans.length) * 100) : 0);
  const sosActiveAlerts = alerts.filter((a) => a.type === "panic_button" && !a.is_read);
  const criticalIncidents = incidents.filter((i) => !isResolved(i) && ["critical", "high"].includes(String(i.severity)));
  const openIncidents = incidents.filter((i) => !isResolved(i));
  const onlineDevices = devices.filter((d) => String(d.status) === "online");
  const offlineDevices = devices.filter((d) => String(d.status) !== "online");
  const lowBattery = devices.filter((d) => Number(d.battery_level ?? d.current_battery_level ?? 100) <= 20).length;
  const gpsHealthy = devices.filter((d) => d.current_gps_lat != null && d.current_gps_lng != null).length;
  const scannedCheckpointIds = new Set(registeredScans.map((s) => s.checkpoint_id).filter(Boolean));
  const readyReports = reports.length + jobs.filter((j) => j.status === "completed").length;
  const failedReportJobs = jobs.filter((j) => j.status === "failed").length;
  const healthParts = [patrolCompliance || 0, devices.length ? Math.round((onlineDevices.length / devices.length) * 100) : 100, Math.max(0, 100 - sosActiveAlerts.length * 30), Math.max(0, 100 - criticalIncidents.length * 18 - Math.max(0, openIncidents.length - criticalIncidents.length) * 6), scans.length ? Math.round((registeredScans.length / scans.length) * 100) : 100, Math.max(0, 100 - pendingTags.length * 8)];
  const healthScore = Math.max(0, Math.min(100, Math.round(healthParts.reduce((sum, value) => sum + value, 0) / healthParts.length)));
  const mainRisk = sosActiveAlerts.length ? `${sosActiveAlerts.length} active SOS` : criticalIncidents.length ? `${criticalIncidents.length} critical incidents` : offlineDevices.length ? `${offlineDevices.length} offline devices` : pendingTags.length ? `${pendingTags.length} pending tags` : "No major risk";
  const healthLabel = healthScore >= 90 ? "Healthy" : healthScore >= 75 ? "Needs Attention" : "Critical";
  const latestScan = scans[0] ? activityFromScan(scans[0]) : undefined;
  const latestSos = alerts[0] ? activityFromAlert(alerts[0]) : undefined;
  const latestIncident = incidents[0] ? activityFromIncident(incidents[0]) : undefined;
  const latestDevice = devices[0] ? activityFromDevice(devices[0]) : undefined;
  const latestReport = reports[0] ? activityFromReport(reports[0]) : undefined;
  const latestCheckpoint = pendingTags[0] ? activityFromPendingTag(pendingTags[0]) : checkpoints[0] ? activity("checkpoint-" + checkpoints[0].id, "Checkpoint registered", checkpoints[0].name, "/checkpoints", checkpoints[0].created_at, "normal", siteName(checkpoints[0])) : undefined;
  const latestAi = aiInsights[0] ? activity("ai-" + aiInsights[0].id, aiInsights[0].summary ?? titleCase(aiInsights[0].type ?? "AI insight"), "AI Intelligence", "/ai-insights", aiInsights[0].created_at, aiInsights[0].severity === "critical" ? "critical" : "info", selectedSiteName) : undefined;
  const attention = groupAttention([...sosActiveAlerts.map((alert) => attentionItem("sos-" + alert.id, "SOS Alert", alert.message ?? "Panic button pressed", selectedSiteName, alert.is_read ? "Acknowledged" : "Awaiting acknowledgement", "/sos-alerts", alert.created_at, "critical")), ...criticalIncidents.map((incident) => attentionItem("incident-" + incident.id, "Critical Incident", incident.title ?? "Incident", siteName(incident, selectedSiteName), "Open", "/incidents", incident.created_at, "critical")), ...missedSessions.map((session) => attentionItem("session-" + session.id, "Missed Patrol", patrolSessionLabel(session), siteName(session, selectedSiteName), titleCase(String(session.status)), "/session-logs", session.updated_at ?? session.scheduled_start, "warning")), ...offlineDevices.slice(0, 3).map((device) => attentionItem("device-" + device.id, "Device Offline", deviceIdentity(device), siteName(device, selectedSiteName), "Offline", "/devices", device.last_seen_at, "warning")), ...pendingTags.slice(0, 3).map((tag) => attentionItem("tag-" + tag.id, "Unregistered Tag", tag.tag_uid ?? tag.nfc_tag_id ?? "Pending NFC tag", siteName(tag, selectedSiteName), "Registration pending", "/checkpoints", tag.scanned_at ?? tag.last_seen_at ?? tag.created_at, "warning"))]).slice(0, 6);
  const activityEvents = [...scans.slice(0, 20).map(activityFromScan), ...alerts.slice(0, 10).map(activityFromAlert), ...incidents.slice(0, 10).map(activityFromIncident), ...devices.slice(0, 10).map(activityFromDevice), ...reports.slice(0, 8).map(activityFromReport), ...jobs.slice(0, 8).map((job) => activity("job-" + job.id, `${titleCase(job.report_type ?? "Report")} job ${titleCase(job.status ?? "updated")}`, job.error_message ?? job.sites?.name ?? "Report job", "/reports", job.completed_at ?? job.failed_at ?? job.created_at, job.status === "failed" ? "warning" : "info", job.sites?.name ?? selectedSiteName))].filter(Boolean).sort((a, b) => new Date(b.timestamp ?? 0).getTime() - new Date(a.timestamp ?? 0).getTime()).slice(0, 30);
  return { healthScore, healthLabel, mainRisk, patrolCompliance, sessionsExpected: expectedSessions.length, sessionsCompleted: completedSessions.length, lateSessions: lateSessions.length, missedSessions: missedSessions.length, activeSessions, nextSession, sosActive: sosActiveAlerts.length, sosUnacknowledged: sosActiveAlerts.length, openIncidents: openIncidents.length, criticalIncidents: criticalIncidents.length, devicesOnline: onlineDevices.length, devicesOffline: offlineDevices.length, devicesTotal: devices.length, lowBattery, gpsHealthy, scansToday: scans.length, registeredScans: registeredScans.length, unregisteredScans: unregisteredScans.length, scannedCheckpoints: scannedCheckpointIds.size, checkpointsTotal: checkpoints.length, pendingTags: pendingTags.length, reportsGenerated: reports.length, readyReports, failedReportJobs, aiInsights, attention, activity: activityEvents, latestScan, latestSos, latestIncident, latestDevice, latestReport, latestCheckpoint, latestAi };
}

function isResolved(row: AnyRow) { return row.resolved === true || ["resolved", "closed"].includes(String(row.status)); }
function eventTime(row: AnyRow) { return String(row.created_at ?? row.event_occurred_at ?? row.scanned_at ?? row.updated_at ?? ""); }
function titleCase(value: string) { return value.replace(/_/g, " ").replace(/\b\w/g, (char) => char.toUpperCase()); }
function siteName(row: AnyRow, fallback = "All Sites") { return row.sites?.name ?? row.checkpoints?.sites?.name ?? fallback; }
function checkpointName(scan: AnyRow) { return scan.checkpoints?.name ?? (scan.tag_uid ? `Tag ${scan.tag_uid}` : "Checkpoint scan"); }
function deviceIdentity(row: AnyRow) { return row.device_name ?? row.device_identifier ?? row.device_id ?? "Patrol device"; }
function activity(id: string, title: string, subtitle: string | undefined, route: string, timestamp: string | null | undefined, severity: Severity, site?: string): ActivityEvent { return { id, title, subtitle, route, timestamp, severity, site }; }
function activityFromScan(scan: AnyRow) { return activity("scan-" + scan.id, scan.tag_status === "unregistered" ? "Unregistered tag scanned" : "Checkpoint scanned", `${checkpointName(scan)} - ${deviceIdentity(scan)}`, "/scan-logs", eventTime(scan), scan.tag_status === "unregistered" ? "warning" : "normal", siteName(scan)); }
function activityFromAlert(alert: AnyRow) { return activity("alert-" + alert.id, alert.is_read ? "SOS acknowledged" : "SOS triggered", alert.message ?? "Panic button alert", "/sos-alerts", eventTime(alert), alert.is_read ? "warning" : "critical"); }
function activityFromIncident(incident: AnyRow) { return activity("incident-" + incident.id, incident.title ?? "Incident created", incident.resolved ? "Resolved" : "Open", "/incidents", incident.created_at, ["critical", "high"].includes(String(incident.severity)) ? "critical" : "warning", siteName(incident)); }
function activityFromDevice(device: AnyRow) { return activity("device-" + device.id, `${deviceIdentity(device)} ${device.status ?? "updated"}`, device.battery_level != null ? `Battery ${device.battery_level}%` : siteName(device), "/devices", device.last_seen_at, device.status === "online" ? "normal" : "offline", siteName(device)); }
function activityFromReport(report: AnyRow) { return activity("report-" + report.id, `${titleCase(report.report_type ?? "Daily")} report generated`, report.summary_text ?? "Ready for review", "/reports", report.generated_at, "info"); }
function activityFromPendingTag(tag: AnyRow) { return activity("pending-" + tag.id, "Unregistered tag awaiting registration", tag.tag_uid ?? tag.nfc_tag_id ?? "Pending tag", "/checkpoints", tag.scanned_at ?? tag.last_seen_at ?? tag.created_at, "warning", siteName(tag)); }
function attentionItem(id: string, title: string, subject: string, site: string, state: string, route: string, timestamp: string | null | undefined, severity: AttentionItem["severity"]): AttentionItem { return { id, title, subject, site, state, route, timestamp, severity }; }
function groupAttention(items: AttentionItem[]) { const seen = new Set<string>(); return items.filter((item) => { const key = `${item.title}-${item.subject}-${item.site}-${item.state}`; if (seen.has(key)) return false; seen.add(key); return true; }); }
function dateRangeLabel(range: DateRange) { return range === "today" ? "Today" : range === "7d" ? "Last 7 Days" : "Last 30 Days"; }
function freshness(timestamp?: string | null) { if (!timestamp) return "No timestamp"; const age = Date.now() - new Date(timestamp).getTime(); const label = formatDistanceToNow(new Date(timestamp), { addSuffix: true }); if (age < 60_000) return "Live"; if (age < 15 * 60_000) return label; if (new Date(timestamp).toDateString() === new Date().toDateString()) return `Old - ${label}`; return `Historical - ${label}`; }

function PatrolsStatusPanel({ sessions, devices }: { sessions: AnyRow[]; devices: AnyRow[] }) {
  return <section className='mb-4 overflow-hidden rounded-xl border border-white/10 bg-slate-950/72'><div className='flex items-center justify-between border-b border-white/10 px-4 py-3'><h2 className='text-sm font-black uppercase tracking-[0.14em] text-white'>Patrols</h2><Link to='/patrols' className='text-xs font-bold text-cyan-300 hover:text-cyan-200'>Open Patrols</Link></div><div className='overflow-auto'>{sessions.length ? <table className='w-full min-w-[1080px] text-left text-sm'><thead className='border-b border-white/10 text-[10px] font-black uppercase tracking-wider text-slate-500'><tr><th className='px-3 py-3'>Patrol</th><th className='px-3 py-3'>Device</th><th className='px-3 py-3'>Site</th><th className='px-3 py-3'>Progress</th><th className='px-3 py-3'>Current Checkpoint</th><th className='px-3 py-3'>Next Checkpoint</th><th className='px-3 py-3'>ETA</th><th className='px-3 py-3'>Status</th><th className='px-3 py-3'>Last Activity</th><th className='px-3 py-3 text-right'>Actions</th></tr></thead><tbody className='divide-y divide-white/5'>{sessions.map((session) => { const progress = patrolSessionProgress(session); const device = findPatrolDevice(session, devices); const tone = patrolStatusTone(session.status); return <tr key={session.id} className='transition hover:bg-white/[0.03]'><td className='px-3 py-3'><div className='flex items-center gap-3'><span className={'h-2.5 w-2.5 rounded-full ' + solidPatrolDot(tone)} /><div><p className='font-black text-white'>{patrolSessionLabel(session)}</p><p className='text-xs text-slate-500'>{session.patrol_schedules?.name || 'On demand'}</p></div></div></td><td className='px-3 py-3'><p className='font-bold text-white'>{patrolDeviceLabel(device, session)}</p><p className='text-xs text-slate-500'>{device?.battery_level != null ? String(device.battery_level) + '% battery' : 'Battery unknown'}</p></td><td className='px-3 py-3 text-slate-300'>{patrolSiteName(session, device)}</td><td className='px-3 py-3'><div className='flex items-center gap-2'><div className='h-2 flex-1 rounded-full bg-white/10'><div className={'h-2 rounded-full ' + solidPatrolDot(tone)} style={{ width: Math.min(Math.max(progress.percent, 0), 100) + '%' }} /></div><span className='w-20 text-xs text-slate-400'>{progress.completed}/{progress.total || 0} {progress.percent}%</span></div></td><td className='px-3 py-3 text-slate-300'>{currentPatrolCheckpoint(session) || 'Awaiting start'}</td><td className='px-3 py-3 text-slate-300'>{nextPatrolCheckpoint(session) || 'Route complete'}</td><td className='px-3 py-3 font-semibold text-slate-300'>{patrolEtaLabel(session)}</td><td className='px-3 py-3'><span className={'inline-flex w-fit rounded-full border px-2 py-1 text-[10px] font-black uppercase tracking-wider ' + patrolBadgeTone(tone)}>{titleCase(String(patrolMovingStatus(session)))}</span></td><td className='px-3 py-3 text-slate-400'>{freshness(session.last_scan_at ?? session.actual_start ?? session.updated_at ?? session.scheduled_start)}</td><td className='px-3 py-3'><div className='flex justify-end gap-2'><Link to={'/live-patrol?session=' + session.id} className='rounded-md border border-white/10 p-2 text-slate-300 hover:border-emerald-400/40 hover:text-emerald-300' aria-label='View patrol'><Eye className='h-4 w-4' /></Link><Link to={'/live-map?device=' + (session.device_identifier ?? '')} className='rounded-md border border-white/10 p-2 text-slate-300 hover:border-blue-400/40 hover:text-blue-300' aria-label='Open map'><MapIcon className='h-4 w-4' /></Link><Link to={'/session-logs?session=' + session.id} className='rounded-md border border-white/10 p-2 text-slate-300 hover:border-cyan-400/40 hover:text-cyan-300' aria-label='Open session'><FileText className='h-4 w-4' /></Link></div></td></tr>; })}</tbody></table> : <div className='p-6 text-center'><p className='font-bold text-white'>No patrol sessions for this period</p><p className='mt-2 text-sm text-slate-400'>Scheduled patrols will appear here when sessions are generated.</p></div>}</div></section>;
}
function HeaderPill({ icon: Icon, label, tone }: { icon: IconComponent; label: string; tone: Severity }) { return <span className={`inline-flex h-10 items-center gap-2 rounded-lg border px-3 text-xs font-semibold ${toneClass(tone).soft}`}><Icon className="h-4 w-4" />{label}</span>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="space-y-1 text-[10px] font-black uppercase tracking-[0.18em] text-slate-500">{label}{children}</label>; }
function KpiCard({ icon: Icon, title, value, detail, tone, subtext }: { icon: IconComponent; title: string; value: string | number; detail: string; tone: Severity; subtext?: string }) { const style = toneClass(tone); return <article className={`rounded-xl border bg-slate-950/72 p-4 ${style.border}`}><div className="mb-3 flex items-start justify-between"><div className={`flex h-11 w-11 items-center justify-center rounded-xl border ${style.icon}`}><Icon className="h-5 w-5" /></div><span className={`text-[10px] font-black uppercase ${style.text}`}>{detail}</span></div><p className="text-xs font-black uppercase tracking-[0.14em] text-slate-400">{title}</p><p className="mt-1 text-3xl font-black text-white">{value}</p>{subtext && <p className="mt-2 text-xs text-slate-400">{subtext}</p>}</article>; }
function AttentionCard({ item }: { item: AttentionItem }) { const style = toneClass(item.severity); return <Link to={item.route} className={`block rounded-xl border bg-slate-950/76 p-4 transition hover:-translate-y-0.5 ${style.border}`}><div className="mb-2 flex items-center justify-between gap-2"><span className={`text-xs font-black uppercase ${style.text}`}>{item.title}</span><span className="text-xs text-slate-500">{freshness(item.timestamp)}</span></div><p className="font-bold text-white">{item.subject}</p><p className="mt-1 text-sm text-slate-400">{item.site} - {item.state}</p><span className={`mt-3 inline-flex rounded-lg border px-3 py-1 text-xs font-bold ${style.soft}`}>Open</span></Link>; }
function OperationsPanel({ title, action, route, badge, children }: { title: string; action: string; route: string; badge: string; children: ReactNode }) { return <section className="rounded-xl border border-white/10 bg-slate-950/72 p-4"><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-black uppercase tracking-[0.14em] text-white">{title}</h2><span className="rounded-full border border-emerald-400/20 bg-emerald-400/10 px-2 py-1 text-[10px] font-black uppercase text-emerald-300">{badge}</span></div>{children}<Link to={route} className="mt-3 inline-flex text-sm font-semibold text-cyan-300 hover:text-cyan-200">{action}</Link></section>; }
function ActivityRow({ event }: { event: ActivityEvent }) { const style = toneClass(event.severity); return <Link to={event.route} className="flex gap-3 rounded-lg border border-white/10 bg-white/[0.03] p-3 transition hover:border-cyan-400/25"><span className={`mt-1 h-2.5 w-2.5 shrink-0 rounded-full ${style.dot}`} /><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><p className="truncate text-sm font-bold text-white">{event.title}</p><span className={`shrink-0 text-xs ${style.text}`}>{freshness(event.timestamp)}</span></div><p className="mt-1 truncate text-xs text-slate-400">{event.subtitle}</p>{event.site && <p className="mt-1 text-[10px] uppercase tracking-wider text-slate-600">{event.site}</p>}</div></Link>; }
function PatrolSessionCard({ session }: { session: AnyRow }) { const progress = patrolSessionProgress(session); return <Link to="/live-patrol" className="block rounded-lg border border-white/10 bg-white/[0.03] p-3 hover:border-emerald-400/30"><div className="flex items-start justify-between"><div><p className="font-bold text-white">{patrolSessionLabel(session)}</p><p className="text-xs text-slate-400">{deviceIdentity(session)} - {siteName(session)}</p></div><span className="rounded-md border border-emerald-400/20 bg-emerald-400/10 px-2 py-1 text-[10px] font-black uppercase text-emerald-300">{titleCase(String(session.status))}</span></div><div className="mt-3 flex items-center gap-3"><div className="h-2 flex-1 rounded-full bg-white/10"><div className="h-2 rounded-full bg-emerald-400" style={{ width: `${Math.min(100, progress.percent)}%` }} /></div><span className="text-xs text-slate-300">{progress.completed}/{progress.total || "?"}</span></div><p className="mt-2 text-xs text-slate-500">Last activity: {freshness(session.updated_at ?? session.actual_start ?? session.scheduled_start)}</p></Link>; }
function NoActivePatrol({ next }: { next?: AnyRow }) { return <div className="rounded-lg border border-white/10 bg-white/[0.03] p-5 text-sm text-slate-400"><p className="font-bold text-white">No active patrols</p><p className="mt-1">{next ? `Next scheduled: ${patrolSessionLabel(next)} at ${format(new Date(next.scheduled_start), "HH:mm")}` : "No upcoming scheduled patrol in this filter."}</p></div>; }
function StateLine({ icon: Icon, text }: { icon: IconComponent; text: string }) { return <div className="flex items-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] p-3 text-sm text-slate-300"><Icon className="h-4 w-4 text-emerald-300" />{text}</div>; }
function QuickAction({ to, label, critical, muted }: { to: string; label: string; critical?: boolean; muted?: boolean }) { return <Link to={to} className={`rounded-lg border px-3 py-2 text-center text-xs font-bold transition hover:-translate-y-0.5 ${critical ? "border-red-400/40 bg-red-500/15 text-red-200" : muted ? "border-slate-600/70 bg-slate-500/10 text-slate-400" : "border-emerald-400/20 bg-emerald-400/10 text-emerald-200"}`}>{label}</Link>; }
function patrolCheckpoints(session: AnyRow) { return [...(session?.patrol_session_checkpoints ?? [])].sort((a: AnyRow, b: AnyRow) => Number(a.sequence_order ?? 0) - Number(b.sequence_order ?? 0)); }
function patrolCheckpointName(checkpoint: AnyRow | undefined) { return checkpoint?.checkpoints?.name ?? checkpoint?.checkpoint_name ?? checkpoint?.name ?? ''; }
function currentPatrolCheckpoint(session: AnyRow) { const checkpoints = patrolCheckpoints(session); const current = checkpoints.find((checkpoint) => checkpoint.status === 'current' || checkpoint.status === 'in_progress') ?? [...checkpoints].reverse().find((checkpoint) => checkpoint.scanned_at || checkpoint.status === 'completed' || checkpoint.status === 'scanned'); return patrolCheckpointName(current); }
function nextPatrolCheckpoint(session: AnyRow) { return patrolCheckpointName(patrolCheckpoints(session).find((checkpoint) => !checkpoint.scanned_at && !['completed', 'scanned', 'missed', 'skipped'].includes(String(checkpoint.status)))); }
function findPatrolDevice(session: AnyRow, devices: AnyRow[]) { return devices.find((device) => session.device_identifier && device.device_identifier === session.device_identifier) ?? devices.find((device) => session.device_id && device.id === session.device_id) ?? null; }
function patrolDeviceLabel(device: AnyRow | null, session: AnyRow) { const value = device?.device_name || session?.device_name || session?.device_identifier || session?.device_id || 'Unassigned device'; return String(value).startsWith('mxp-') ? 'RG360-' + String(value).slice(-6).toUpperCase() : String(value); }
function patrolSiteName(session: AnyRow, device: AnyRow | null) { return session?.sites?.name || device?.sites?.name || session?.site_name || 'Unassigned site'; }
function patrolEtaLabel(session: AnyRow) { if (!nextPatrolCheckpoint(session)) return '-'; const progress = patrolSessionProgress(session); const remaining = Math.max(Number(progress.total || 0) - Number(progress.completed || 0), 0); return remaining ? String(Math.max(remaining * 3, 3)) + ' min' : '-'; }
function patrolMovingStatus(session: AnyRow) { if (['active', 'in_progress'].includes(String(session.status)) && session.last_scan_at && Date.now() - new Date(session.last_scan_at).getTime() < 2 * 60000) return 'moving'; return session.status || 'scheduled'; }
function patrolStatusTone(status?: string | null): Severity { if (['completed', 'completed_late'].includes(String(status))) return 'normal'; if (['active', 'in_progress', 'running', 'awaiting_start'].includes(String(status))) return 'info'; if (['completed_late', 'late', 'late_start', 'delayed'].includes(String(status))) return 'warning'; if (['missed', 'incomplete'].includes(String(status))) return 'critical'; return 'offline'; }
function patrolBadgeTone(tone: Severity) { if (tone === 'critical') return 'border-red-400/30 bg-red-400/10 text-red-300'; if (tone === 'warning') return 'border-amber-400/30 bg-amber-400/10 text-amber-300'; if (tone === 'info') return 'border-blue-400/30 bg-blue-400/10 text-blue-300'; if (tone === 'normal') return 'border-emerald-400/30 bg-emerald-400/10 text-emerald-300'; return 'border-white/10 bg-white/5 text-slate-300'; }
function solidPatrolDot(tone: Severity) { if (tone === 'critical') return 'bg-red-400'; if (tone === 'warning') return 'bg-amber-400'; if (tone === 'info') return 'bg-blue-400'; if (tone === 'normal') return 'bg-emerald-400'; return 'bg-slate-500'; }
function toneClass(tone: Severity) { const classes = { normal: { border: "border-emerald-400/24", text: "text-emerald-300", soft: "border-emerald-400/20 bg-emerald-400/10 text-emerald-300", icon: "border-emerald-400/25 bg-emerald-400/10 text-emerald-300", dot: "bg-emerald-400" }, info: { border: "border-sky-400/24", text: "text-sky-300", soft: "border-sky-400/20 bg-sky-400/10 text-sky-300", icon: "border-sky-400/25 bg-sky-400/10 text-sky-300", dot: "bg-sky-400" }, warning: { border: "border-amber-400/35", text: "text-amber-300", soft: "border-amber-400/25 bg-amber-400/10 text-amber-300", icon: "border-amber-400/30 bg-amber-400/10 text-amber-300", dot: "bg-amber-400" }, critical: { border: "border-red-400/45 shadow-[0_0_28px_rgba(239,68,68,0.12)]", text: "text-red-300", soft: "border-red-400/30 bg-red-500/15 text-red-300", icon: "border-red-400/30 bg-red-500/15 text-red-300", dot: "bg-red-400" }, offline: { border: "border-slate-600/70", text: "text-slate-400", soft: "border-slate-600/70 bg-slate-500/10 text-slate-400", icon: "border-slate-500/30 bg-slate-500/10 text-slate-400", dot: "bg-slate-500" } } satisfies Record<Severity, { border: string; text: string; soft: string; icon: string; dot: string }>; return classes[tone]; }





function buildCommandPanels(model: ReturnType<typeof buildOperationsModel>, routes: AnyRow[], schedules: AnyRow[]): CommandPanelModel[] {
  const activeRoutes = routes.filter((route) => !['inactive', 'disabled', 'archived'].includes(String(route.status ?? 'active')));
  const activeRouteIds = new Set(model.activeSessions.map((session: AnyRow) => session.route_id ?? session.patrol_route_id ?? session.patrol_routes?.id).filter(Boolean));
  const routeCheckpointIds = new Set(routes.flatMap((route) => route.patrol_route_checkpoints ?? []).map((row: AnyRow) => row.checkpoint_id ?? row.checkpoints?.id).filter(Boolean));
  const activeSchedules = schedules.filter((schedule) => !['paused', 'inactive', 'disabled', 'archived'].includes(String(schedule.status ?? 'active')));
  const pausedSchedules = schedules.filter((schedule) => ['paused', 'temporarily_paused'].includes(String(schedule.status)));
  const schedulesUsingRoutes = new Set(schedules.map((schedule) => schedule.route_id ?? schedule.patrol_route_id ?? schedule.patrol_routes?.id).filter(Boolean));
  const activeScheduleLinks = activeSchedules.filter((schedule) => schedule.route_id || schedule.patrol_route_id || schedule.patrol_routes?.id).length;
  const devicesPatrolling = new Set(model.activeSessions.map((session: AnyRow) => session.device_id ?? session.device_identifier).filter(Boolean)).size;
  return [
    { title: 'Live Patrol', icon: Zap, route: '/live-patrol', accent: 'normal', metrics: [{ label: 'Active Patrols', value: model.activeSessions.length }, { label: 'Devices Online', value: model.devicesOnline }, { label: 'Devices Patrolling', value: devicesPatrolling }] },
    { title: 'Patrol', icon: ShieldCheck, route: '/patrols', accent: model.missedSessions ? 'warning' : 'info', metrics: [{ label: 'Completed', value: model.sessionsCompleted }, { label: 'Incomplete', value: model.missedSessions }, { label: 'Late Starts', value: model.lateSessions }, { label: 'Completions', value: model.sessionsCompleted }, { label: 'Missed', value: model.missedSessions }] },
    { title: 'Routes', icon: Route, route: '/routes', accent: 'info', metrics: [{ label: 'Total Routes', value: routes.length }, { label: 'Active Routes', value: activeRoutes.length }, { label: 'Currently Active', value: activeRouteIds.size }, { label: 'Checkpoints Used', value: routeCheckpointIds.size }, { label: 'Schedules Using Routes', value: schedulesUsingRoutes.size }, { label: 'Active Schedule Links', value: activeScheduleLinks }] },
    { title: 'Schedules', icon: CalendarDays, route: '/schedules', accent: 'info', metrics: [{ label: 'Total Schedules', value: schedules.length }, { label: 'All Active Schedules', value: activeSchedules.length }, { label: 'Currently Running', value: model.activeSessions.length }, { label: 'Starting Later Today', value: 'N/A', hint: 'needs run window' }, { label: 'Paused', value: pausedSchedules.length }, { label: 'Rate', value: String(model.patrolCompliance) + '%' }] },
    { title: 'Scan Logs', icon: Crosshair, route: '/scan-logs', accent: model.unregisteredScans ? 'warning' : 'normal', metrics: [{ label: 'Total Scans', value: model.scansToday }, { label: 'Registered', value: model.registeredScans }, { label: 'Checkpoint Matched', value: model.scannedCheckpoints }, { label: 'Unregistered', value: model.unregisteredScans }, { label: 'Pending Review', value: model.pendingTags }, { label: 'Pending Sync', value: 'N/A', hint: 'local queue' }] },
    { title: 'Reports', icon: FileText, route: '/reports', accent: model.failedReportJobs ? 'warning' : 'info', metrics: [{ label: 'Generated', value: model.reportsGenerated }, { label: 'Ready', value: model.readyReports }, { label: 'Failed', value: model.failedReportJobs }] },
    { title: 'Incidents', icon: AlertTriangle, route: '/incidents', accent: model.criticalIncidents ? 'critical' : model.openIncidents ? 'warning' : 'info', metrics: [{ label: 'Total Incidents', value: 'N/A', hint: 'scope query' }, { label: 'Open', value: model.openIncidents }, { label: 'Requires Attention', value: model.criticalIncidents }, { label: 'High Priority', value: model.criticalIncidents }, { label: 'Resolved', value: 'N/A', hint: 'status only' }, { label: 'SOS Linked', value: 'N/A', hint: 'needs relation' }] },
    { title: 'Checkpoints', icon: MapPin, route: '/checkpoints', accent: model.pendingTags ? 'warning' : 'normal', metrics: [{ label: 'Total Checkpoints', value: model.checkpointsTotal }, { label: 'Filtered', value: model.checkpointsTotal }, { label: 'Registered', value: model.checkpointsTotal - model.pendingTags }, { label: 'Active', value: model.checkpointsTotal }, { label: 'UID Assigned', value: model.checkpointsTotal - model.pendingTags }, { label: 'Not Scanned', value: Math.max(model.checkpointsTotal - model.scannedCheckpoints, 0) }] },
    { title: 'SOS', icon: ShieldAlert, route: '/sos-alerts', accent: model.sosActive ? 'critical' : 'normal', metrics: [{ label: 'Active SOS', value: model.sosActive }, { label: 'Acknowledged', value: model.sosUnacknowledged ? 0 : 'N/A', hint: 'is_read only' }, { label: 'Requires Backend Status Fields', value: model.sosActive }, { label: 'Resolved Today', value: 'N/A', hint: 'no resolved field' }, { label: 'Avg Response', value: 'N/A', hint: 'no ack time' }, { label: 'False Alarm', value: 'N/A', hint: 'no flag' }] },
    { title: 'Devices', icon: Smartphone, route: '/devices', accent: model.devicesOffline ? 'warning' : 'info', metrics: [{ label: 'Total Devices', value: model.devicesTotal }, { label: 'Online', value: model.devicesOnline }, { label: 'Offline', value: model.devicesOffline }, { label: 'Low Battery', value: model.lowBattery }] },
  ];
}
function CommandPanel({ panel }: { panel: CommandPanelModel }) { const Icon = panel.icon; const style = toneClass(panel.accent); return <Link to={panel.route} className={"block rounded-xl border bg-slate-950/72 p-4 transition hover:-translate-y-0.5 hover:border-cyan-300/45 " + style.border}><div className="mb-3 flex items-center gap-2"><Icon className={"h-4 w-4 " + style.text} /><h2 className={"text-sm font-black uppercase tracking-[0.12em] " + style.text}>{panel.title}</h2></div><div className="grid grid-cols-3 gap-2">{panel.metrics.map((metric) => <MetricTile key={panel.title + "-" + metric.label} metric={metric} />)}</div></Link>; }
function MetricTile({ metric }: { metric: CommandMetric }) { const style = toneClass(metric.tone ?? "info"); return <div className="min-h-20 rounded-lg border border-white/10 bg-white/[0.03] p-2"><p className="text-xl font-black text-white">{metric.value}</p><p className="mt-1 text-[10px] font-semibold leading-tight text-slate-400">{metric.label}</p>{metric.hint && <p className={"mt-1 text-[9px] font-bold uppercase " + style.text}>{metric.hint}</p>}</div>; }
